import{_ as t,a,c as i,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 26 Where is it?","description":"学习 there is 与位置介词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 26 Where is it?","description":"学习 there is 与位置介词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 there is 与位置介词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 25 Mrs. Smith's kitchen","link":"/life/english/new-concept/book-1/unit-02/lesson-025"},"next":{"text":"第一册：英语初阶 · Lesson 27 Mrs. Smith's living room","link":"/life/english/new-concept/book-1/unit-02/lesson-027"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 25 Mrs. Smith's kitchen","link":"/life/english/new-concept/book-1/unit-02/lesson-025"},"next":{"text":"第一册：英语初阶 · Lesson 27 Mrs. Smith's living room","link":"/life/english/new-concept/book-1/unit-02/lesson-027"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-02/lesson-026.md","filePath":"life/english/new-concept/book-1/unit-02/lesson-026.md"}`),o={name:"life/english/new-concept/book-1/unit-02/lesson-026.md"};function s(r,e,l,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-26-where-is-it" tabindex="-1">第一册：英语初阶 · Lesson 26 Where is it? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-26-where-is-it" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 26 Where is it?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元 2</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-025">配套课 Lesson 25</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>描述厨房物品的位置 本课要掌握there is 与位置介词，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>kitchen</td><td>/ˈkɪtʃɪn/</td><td>n.</td><td>厨房</td><td>in the kitchen</td></tr><tr><td>refrigerator</td><td>/rɪˈfrɪdʒəreɪtə/</td><td>n.</td><td>冰箱</td><td>a small refrigerator</td></tr><tr><td>cupboard</td><td>/ˈkʌbəd/</td><td>n.</td><td>橱柜</td><td>in the cupboard</td></tr><tr><td>near</td><td>/nɪə/</td><td>prep.</td><td>在附近</td><td>near the door</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>there is — 引出存在的单数对象</li><li>in the cupboard — 在柜子内部</li></ul><h2 id="语法讲解-there-is-与位置介词" tabindex="-1">语法讲解：there is 与位置介词 <a class="header-anchor" href="#语法讲解-there-is-与位置介词" aria-label="Permalink to &quot;语法讲解：there is 与位置介词&quot;">​</a></h2><p>there is 用于引出某处存在的单数物品，后接 a/an + 单数名词；说某个已知物品在哪里则用 The ... is ...。in 表内部，on 表在表面，near 表附近。先区分“这里有一个什么”和“那个东西在哪里”，两种句型的信息起点不同。介词短语本身不能替代句子的谓语。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The kettle is on the shelf.</p></blockquote><p>水壶在架子上。</p><p>The kettle 是已知物品，is 后用 on the shelf 说明它的位置；不是首次介绍“这里有什么”的存在句。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>There is the kettle 常不适合首次引入物品；首次介绍通常用 a kettle。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“The kettle is on the shelf.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The kettle is on the shelf. There is a clock above the fridge.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“描述厨房物品的位置”写两至三句，再读给同伴听。至少使用一次there is 与位置介词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>The kettle 是已知物品，is 后用 on the shelf 说明它的位置；不是首次介绍“这里有什么”的存在句。 There is 引出新信息 a clock；above the fridge 说明时钟高于冰箱，不保证与冰箱表面接触。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 on/in：水壶在架子表面，The kettle is ___ the shelf.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> on</p><p><strong>解析：</strong> 按本课规则判断：there is 用于引出某处存在的单数物品，后接 a/an + 单数名词；说某个已知物品在哪里则用 The ... is ...。in 表内部，on 表在表面，near 表附近。先区分“这里有一个什么”和“那个东西在哪里”，两种句型的信息起点不同。介词短语本身不能替代句子的谓语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“水壶在架子上。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The kettle is on the shelf.</p><p><strong>解析：</strong> The kettle 是已知物品，is 后用 on the shelf 说明它的位置；不是首次介绍“这里有什么”的存在句。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：There is a clock above the fridge.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 冰箱上方有一只钟。</p><p><strong>解析：</strong> There is 引出新信息 a clock；above the fridge 说明时钟高于冰箱，不保证与冰箱表面接触。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：there is 与位置介词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-025">上一课</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-027">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=t(o,[["render",s]]);export{u as __pageData,k as default};
